            <section data-station-panel="topping" hidden><div class="ingredient-grid">${me.map(n=>`<button class="action-card topping-choice" data-action="topping${n}"><span class="ingredient-art topping-art topping-${me.indexOf(n)}">${W(Tr[n])}</span><strong>${n}</strong><em>＋1 份</em></button>`).join("")}</div><p id="topping-contents" class="station-note" role="status"></p></section>
